import json,hashlib,xml.etree.ElementTree as ET
from pathlib import Path
R=Path(__file__).resolve().parents[1]
S={"winter-park":("Winter Park, Colorado, US (partial)","winter-park-research"),"breckenridge":("Breckenridge, Colorado, US (partial)","breckenridge-research"),"wachusett":("Wachusett Mountain, US","wachusett-research"),"patscherkofel":("Patscherkofel, AT","patscherkofel-research")}
T="""<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Lift-Lap resort review</title><style>body{font:16px system-ui;max-width:1200px;margin:auto;padding:20px;background:#f7faf4;color:#183b3a}.warn{border-left:5px solid #b54112;padding:12px;background:#fff6ed}.grid{display:grid;grid-template-columns:280px 1fr;gap:20px}.box{background:white;border:1px solid #cbdad0;padding:16px;border-radius:8px}.map{width:100%;min-width:0;aspect-ratio:900/560;height:auto}.wrap{overflow:auto;border:1px solid #cbdad0}.e{fill:none;stroke-width:2;cursor:pointer;vector-effect:non-scaling-stroke}.lift{stroke:#203f3f;stroke-dasharray:7 5}.piste{stroke:#326f9c}.selected{stroke:#b54112!important;stroke-width:6}.dis{opacity:.25}.pill{display:inline-block;background:#e8f1eb;border-radius:9px;padding:4px;margin:3px}dt{font-weight:bold;margin-top:8px}dd{margin:0;color:#55706b;overflow-wrap:anywhere}a{color:#94330e}select{max-width:100%}*{box-sizing:border-box}.box{min-width:0}p{overflow-wrap:anywhere}.endpoint{fill:#fff;stroke:#94330e;stroke-width:3}.endpoint-label{fill:#183b3a;font:bold 14px system-ui}.e:focus{stroke:#b54112;stroke-width:6;outline:none}@media(max-width:750px){.grid{grid-template-columns:1fr}}</style><main><h1>Resort data review</h1><p class="warn"><b>Browse-only research preview.</b> Unreviewed geometry; not a route selector. No routing, access, direction, operating, timing, safety, or coverage claims. Do not use for navigation.</p><div class="grid"><aside class="box"><label for="s">Research sample</label><select id="s"></select><p><label><input id="l" type="checkbox" checked> Lifts</label><br><label><input id="p" type="checkbox" checked> Pistes</label><br><label><input id="d" type="checkbox" checked> Include smaller components</label></p><p id="cov"></p><label for="lift-review">Lift endpoint review</label><select id="lift-review"></select><p id="lift-summary"></p></aside><section class="box"><h2>Source geometry</h2><p>Solid lines: pistes (color is not difficulty). Dashed: lifts. Pale: smaller disconnected components. Select a segment for native grade and source.</p><div id="sum"></div><div class="wrap"><svg id="map" class="map" viewBox="0 0 900 560" role="group" aria-label="Unreviewed resort geometry"></svg></div><p id="status" role="status" aria-live="polite">Select a segment.</p><div id="detail" tabindex="-1"></div><section id="lift-detail" aria-label="Source lift endpoint evidence"></section></section></div><section class="box"><h2>Source and review limits</h2><p id="src"></p><p>Native grade is the original OSM tag, not a cross-resort guarantee. Disconnected is structural, not evidence of a connector. Source links are explicit user actions. © OpenStreetMap contributors; ODbL 1.0. This artifact makes no network requests.</p></section></main><script id="data" type="application/json">__DATA__</script><script src="/resort-review.js" defer></script>"""
def main():
 d={}
 for k,(label,n) in S.items():
  x=R/"data/terrain"/n;d[k]={"label":label,"graph":json.loads((x/"graph.json").read_text()),"manifest":json.loads((x/"manifest.json").read_text())}
  if (x/"connectivity-diagnostics.json").exists():
   diag=json.loads((x/"connectivity-diagnostics.json").read_text());m=d[k]['manifest']
   if diag['graph_sha256']!=m['graph_sha256'] or diag['source_sha256']!=m['sanitized_sha256']:raise ValueError('Stale diagnostics')
   root=ET.fromstring((x/'source.osm').read_bytes());coords={v.get('id'):[float(v.get('lon')),float(v.get('lat'))] for v in root.findall('node')}
   supplement=json.loads((x/'station-evidence.json').read_text()) if (x/'station-evidence.json').exists() else None
   if supplement and (supplement['graph_sha256']!=m['graph_sha256'] or supplement['raw_source_sha256']!=m['original_response_sha256']):raise ValueError('Stale station evidence')
   for lift in diag['lifts']:
    for e in lift['endpoint_incidence']:
     e['coordinate']=coords.get(e['source_node'])
     matches=[v for v in supplement['endpoints'] if v['source_node']==e['source_node'] and v['lift_source_ref']==lift['source_ref']] if supplement else []
     e['station_tags']=matches[0]['tags'] if matches else None
   d[k]['diagnostics']=diag
 (R/"web/resort-review.html").write_text(T.replace("__DATA__",json.dumps(d,separators=(",",":")).replace("<","\\u003c")))
if __name__=="__main__":main()
